import datetime
from typing import Union

class TimeUtils:

    TIME_FORMAT = "%H:%M:%S"
    DATE_FORMAT = "%Y-%m-%d"
    DATETIME_FORMAT = "%Y-%m-%d %H:%M:%S"
    SECONDS_PER_MINUTE = 60

    def __init__(self):
        self._datetime = datetime.datetime.now()

    @property
    def datetime(self) -> datetime.datetime:
        return self._datetime

    @datetime.setter
    def datetime(self, value: datetime.datetime):
        self._datetime = value

    def get_current_time(self) -> str:
        return self._format_datetime(self._datetime, self.TIME_FORMAT)

    def get_current_date(self) -> str:
        return self._format_datetime(self._datetime, self.DATE_FORMAT)

    def add_seconds(self, seconds: int) -> str:
        new_datetime = self._datetime + datetime.timedelta(seconds=seconds)
        return self._format_datetime(new_datetime, self.TIME_FORMAT)

    def string_to_datetime(self, string: str) -> datetime.datetime:
        return datetime.datetime.strptime(string, self.DATETIME_FORMAT)

    def datetime_to_string(self, datetime: datetime.datetime) -> str:
        return self._format_datetime(datetime, self.DATETIME_FORMAT)

    def get_minutes(self, string_time1: str, string_time2: str) -> int:
        time1 = self.string_to_datetime(string_time1)
        time2 = self.string_to_datetime(string_time2)
        return self._calculate_minutes_between(time1, time2)

    def get_format_time(self, year: int, month: int, day: int, hour: int, minute: int, second: int) -> str:
        time_item = datetime.datetime(year, month, day, hour, minute, second)
        return self._format_datetime(time_item, self.DATETIME_FORMAT)

    def _format_datetime(self, dt: datetime.datetime, format_str: str) -> str:
        return dt.strftime(format_str)

    def _calculate_minutes_between(self, time1: datetime.datetime, time2: datetime.datetime) -> int:
        return round((time2 - time1).total_seconds() / self.SECONDS_PER_MINUTE)
